const deleteStoryMutation = `-- name: DeleteStoryMutation :one
WITH target AS (
    SELECT story.id, story.sequence_id, story.team_id, story.title, story.description, story.description_html, story.parent_id, story.objective_id, story.status_id, story.assignee_id, story.blocked_by_id, story.blocking_id, story.related_id, story.reporter_id, story.priority, story.sprint_id, story.workspace_id, story.start_date, story.end_date, story.estimate, story.archived_at, story.is_draft, story.created_at, story.updated_at, story.deleted_at, story.search_vector, story.key_result_id, story.completed_at, story.estimate_unit, story.external_creation_key, story.estimated_duration_minutes, story.minimum_focus_block_minutes, story.auto_scheduling_enabled, story.auto_scheduling_locked, story.auto_scheduling_status, story.auto_scheduling_reason, story.auto_scheduling_updated_at
    FROM public.stories AS story
    WHERE story.id = $1
      AND story.workspace_id = $2
      AND story.deleted_at IS NULL
), authorized AS (
    SELECT target.id, target.sequence_id, target.team_id, target.title, target.description, target.description_html, target.parent_id, target.objective_id, target.status_id, target.assignee_id, target.blocked_by_id, target.blocking_id, target.related_id, target.reporter_id, target.priority, target.sprint_id, target.workspace_id, target.start_date, target.end_date, target.estimate, target.archived_at, target.is_draft, target.created_at, target.updated_at, target.deleted_at, target.search_vector, target.key_result_id, target.completed_at, target.estimate_unit, target.external_creation_key, target.estimated_duration_minutes, target.minimum_focus_block_minutes, target.auto_scheduling_enabled, target.auto_scheduling_locked, target.auto_scheduling_status, target.auto_scheduling_reason, target.auto_scheduling_updated_at
    FROM target
    WHERE (
        CAST($3 AS text) = 'system'
        AND EXISTS (
            SELECT 1
            FROM public.users AS system_actor
            WHERE system_actor.user_id = $4
              AND system_actor.is_active = TRUE
              AND system_actor.is_system = TRUE
        )
    ) OR (
        CAST($3 AS text) IN ('human_user', 'oauth_user')
        AND EXISTS (
            SELECT 1
            FROM public.users AS account
            INNER JOIN public.workspace_members AS workspace_member
                ON workspace_member.workspace_id = target.workspace_id
               AND workspace_member.user_id = account.user_id
            INNER JOIN public.team_members AS team_member
                ON team_member.team_id = target.team_id
               AND team_member.user_id = account.user_id
            WHERE account.user_id = $4
              AND account.is_active = TRUE
        )
    ) OR (
        CAST($3 AS text) = 'personal_token'
        AND EXISTS (
            SELECT 1
            FROM public.api_credentials AS credential
            INNER JOIN public.principals AS principal
                ON principal.principal_id = credential.principal_id
               AND principal.workspace_id = credential.workspace_id
            INNER JOIN public.users AS account
                ON account.user_id = principal.subject_user_id
               AND account.is_active = TRUE
            INNER JOIN public.workspace_members AS workspace_member
                ON workspace_member.workspace_id = target.workspace_id
               AND workspace_member.user_id = account.user_id
            INNER JOIN public.team_members AS team_member
                ON team_member.team_id = target.team_id
               AND team_member.user_id = account.user_id
            WHERE credential.credential_id = $5
              AND credential.workspace_id = target.workspace_id
              AND credential.kind = 'personal_access_token'
              AND credential.revoked_at IS NULL
              AND credential.expires_at > $6
              AND principal.status = 'active'
              AND principal.subject_user_id = $4
              AND EXISTS (
                  SELECT 1
                  FROM public.api_credential_scopes AS credential_scope
                  WHERE credential_scope.credential_id = credential.credential_id
                    AND credential_scope.scope = 'stories:write'
              )
              AND (
                  NOT EXISTS (
                      SELECT 1
                      FROM public.api_credential_team_restrictions AS restriction
                      WHERE restriction.credential_id = credential.credential_id
                  )
                  OR EXISTS (
                      SELECT 1
                      FROM public.api_credential_team_restrictions AS restriction
                      WHERE restriction.credential_id = credential.credential_id
                        AND restriction.workspace_id = target.workspace_id
                        AND restriction.team_id = target.team_id
                  )
              )
        )
    )
), permitted AS (
    SELECT authorized.id, authorized.sequence_id, authorized.team_id, authorized.title, authorized.description, authorized.description_html, authorized.parent_id, authorized.objective_id, authorized.status_id, authorized.assignee_id, authorized.blocked_by_id, authorized.blocking_id, authorized.related_id, authorized.reporter_id, authorized.priority, authorized.sprint_id, authorized.workspace_id, authorized.start_date, authorized.end_date, authorized.estimate, authorized.archived_at, authorized.is_draft, authorized.created_at, authorized.updated_at, authorized.deleted_at, authorized.search_vector, authorized.key_result_id, authorized.completed_at, authorized.estimate_unit, authorized.external_creation_key, authorized.estimated_duration_minutes, authorized.minimum_focus_block_minutes, authorized.auto_scheduling_enabled, authorized.auto_scheduling_locked, authorized.auto_scheduling_status, authorized.auto_scheduling_reason, authorized.auto_scheduling_updated_at
    FROM authorized
    WHERE CAST($3 AS text) = 'system'
       OR authorized.reporter_id = $4
       OR EXISTS (
           SELECT 1
           FROM public.workspace_members AS workspace_member
           WHERE workspace_member.workspace_id = authorized.workspace_id
             AND workspace_member.user_id = $4
             AND workspace_member.role = 'admin'
       )
), deleted AS (
    UPDATE public.stories AS story
    SET
        deleted_at = $7,
        updated_at = $7
    FROM permitted
    WHERE story.id = permitted.id
      AND story.workspace_id = permitted.workspace_id
      AND story.updated_at = $8
      AND story.deleted_at IS NULL
    RETURNING story.id, story.deleted_at, story.updated_at
)
SELECT
    EXISTS (SELECT 1 FROM target) AS story_exists,
    EXISTS (SELECT 1 FROM authorized) AS actor_authorized,
    EXISTS (SELECT 1 FROM permitted) AS deletion_permitted,
    EXISTS (SELECT 1 FROM deleted) AS story_deleted,
    (SELECT deleted_at FROM deleted) AS deleted_at
`

