// Story mutation queries deliberately repeat their authorization predicate.
// Credentials only narrow current product membership; they never replace it.
func (q *Queries) GetStoryMutationSnapshot(ctx context.Context, arg GetStoryMutationSnapshotParams) (GetStoryMutationSnapshotRow, error) {
	row := q.db.QueryRow(ctx, getStoryMutationSnapshot,
		arg.StoryID,
		arg.WorkspaceID,
		arg.ActorKind,
		arg.ActorID,
		arg.ActorCredentialID,
		arg.Now,
	)
	var i GetStoryMutationSnapshotRow
	err := row.Scan(
		&i.ID,
		&i.SequenceID,
		&i.TeamID,
		&i.Title,
		&i.Description,
		&i.DescriptionHtml,
		&i.ParentID,
		&i.ObjectiveID,
		&i.StatusID,
		&i.AssigneeID,
		&i.ReporterID,
		&i.Priority,
		&i.SprintID,
		&i.KeyResultID,
		&i.EstimateUnit,
		&i.EstimateScheme,
		&i.EstimatedDurationMinutes,
		&i.MinimumFocusBlockMinutes,
		&i.AutoSchedulingEnabled,
		&i.AutoSchedulingLocked,
		&i.AutoSchedulingStatus,
		&i.AutoSchedulingReason,
		&i.AutoSchedulingUpdatedAt,
		&i.StartDate,
		&i.EndDate,
		&i.CompletedAt,
		&i.DeletedAt,
		&i.ArchivedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.WorkspaceID,
		&i.ExternalCreationKey,
	)
	return i, err
}

const insertAuthorizedStoryLabels = `-- name: InsertAuthorizedStoryLabels :many
INSERT INTO public.story_labels (story_id, label_id)
SELECT
    $1,
    label.label_id
FROM public.labels AS label
WHERE label.label_id = ANY(CAST($2 AS uuid[]))
  AND label.workspace_id = $3
  AND (label.team_id = $4 OR label.team_id IS NULL)
ORDER BY label.label_id
ON CONFLICT (story_id, label_id) DO NOTHING
RETURNING label_id
`

type InsertAuthorizedStoryLabelsParams struct {
	StoryID     uuid.UUID
	LabelIds    []uuid.UUID
	WorkspaceID *uuid.UUID
	TeamID      *uuid.UUID
}

func (q *Queries) InsertAuthorizedStoryLabels(ctx context.Context, arg InsertAuthorizedStoryLabelsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, insertAuthorizedStoryLabels,
		arg.StoryID,
		arg.LabelIds,
		arg.WorkspaceID,
		arg.TeamID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var label_id uuid.UUID
		if err := rows.Scan(&label_id); err != nil {
			return nil, err
		}
		items = append(items, label_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

